script:
(function() {
  // Poppins — document-level so it reaches this block's shadow root.
  try {
    if (!document.querySelector('link[data-pr-poppins]')) {
      var pf = document.createElement('link'); pf.rel = 'stylesheet'; pf.setAttribute('data-pr-poppins', '1');
      pf.href = 'https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch (e) {}

  var host  = root_element.querySelector('[data-prn-crops]');
  var empty = root_element.querySelector('[data-prn-empty]');
  if (!host) return;

  var esc = (window.frappe && frappe.utils && frappe.utils.escape_html)
    ? frappe.utils.escape_html
    : function(s) { return (s || '').replace(/[&<>"']/g, function(c) {
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); };

  // The app's pages, in its sidebar order. Inner SVG only (lucide); the
  // wrapper is written once below so every tile draws the same way.
  var VIEWS = [
    ['overview', 'Overview', 'KPIs for the week', '<rect x="3" y="3" width="7" height="9"/><rect x="14" y="3" width="7" height="5"/><rect x="14" y="12" width="7" height="9"/><rect x="3" y="16" width="7" height="5"/>'],
    ['plan', 'Weekly Plan', 'Tasks and tick-off', '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/><path d="m9 16 2 2 4-4"/>'],
    ['blocks', 'Blocks', 'Units and areas', '<path d="M14.1 6 9.9 4 3 7v13l6.9-3 4.2 2L21 16V3z"/><path d="M9.9 4v13M14.1 6v13"/>'],
    ['cycles', 'Crop Cycles', 'Planting to harvest', '<path d="M7 20h10"/><path d="M10 20c5.5-2.5.8-6.4 3-10"/><path d="M9.5 9.4c1.1.8 1.8 2.2 2.3 3.7-2 .4-3.5.4-4.8-.3-1.2-.6-2.3-1.9-3-4.2 2.8-.5 4.4 0 5.5.8z"/><path d="M14.1 6a7 7 0 0 0-1.1 4c1.9-.1 3.3-.6 4.3-1.4 1-1 1.6-2.3 1.7-4.6-2.7.1-4 1-4.9 2z"/>'],
    ['value-adders', 'Value Adders', 'Work done and pay', '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>'],
    ['costs', 'Block Costs', 'Labour, inputs, value', '<path d="M19 7V4a1 1 0 0 0-1-1H5a2 2 0 0 0 0 4h15a1 1 0 0 1 1 1v4h-3a2 2 0 0 0 0 4h3a1 1 0 0 0 1-1v-2a1 1 0 0 0-1-1"/><path d="M3 5v14a2 2 0 0 0 2 2h15a1 1 0 0 0 1-1v-4"/>'],
    ['forecast', 'Forecast', 'Forecast vs actual', '<path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/>'],
    ['settings', 'Settings', 'Rates and protocols', '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>']
  ];

  // Added to every crop's tiles.
  var APPROVALS = ['approvals', 'Approvals', 'Review supervisors\' work', '<path d="M9 12l2 2 4-4"/><path d="M21 12c0 4.97-4.03 9-9 9s-9-4.03-9-9 4.03-9 9-9 9 4.03 9 9z"/>'];
  var MAP = ['map', 'Coverage Map', 'Plan progress by block', '<path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="3"/>'];
  // Extra views only some crops have, keyed by Production Crop.crop_key.
  var EXTRA = {
    'avocado': [
      ['outlook', 'Season Outlook', 'Forecast for the season', '<path d="M3 3v18h18"/><path d="m19 9-5 5-4-4-3 3"/>'],
      ['block-forecast', 'Block Forecast', 'Yield by block', '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/>'],
      ['harvest-calendar', 'Harvest Calendar', 'When blocks are ready', '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>'],
      ['picking-plan', 'Picking Plan', 'Labour for the harvest', '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/>'],
      ['dry-matter', 'Dry Matter', 'Fruit maturity', '<path d="M12 2.7l5.7 5.7a8 8 0 1 1-11.4 0z"/>']
    ],
    'apiary': [
      ['hive-inspections', 'Hive Inspections', 'Colony health checks', '<path d="M11 2a2 2 0 0 0-2 2v5H4a2 2 0 0 0-2 2v2c0 1.1.9 2 2 2h5v5c0 1.1.9 2 2 2h2c1.1 0 2-.9 2-2v-5h5a2 2 0 0 0 2-2v-2a2 2 0 0 0-2-2h-5V4a2 2 0 0 0-2-2z"/>'],
      ['honey-harvest', 'Honey Harvest', 'Supers and yield', '<path d="M12 2l8 4.5v9L12 20l-8-4.5v-9z"/>']
    ],
    'aquaculture': [
      ['pond-batches', 'Pond Batches', 'Stocking and growth', '<path d="M6.5 12c.94-3.46 4.94-6 8.5-6 3.56 0 6.06 2.54 7 6-.94 3.47-3.44 6-7 6s-7.56-2.53-8.5-6z"/><path d="M18 12v.5"/><path d="M16 17.93a9.77 9.77 0 0 1 0-11.86"/>'],
      ['water-quality', 'Water Quality', 'Readings by pond', '<path d="M12 2.7l5.7 5.7a8 8 0 1 1-11.4 0z"/>'],
      ['feeding', 'Feeding & Mortality', 'Feed given and losses', '<path d="M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2"/><path d="M7 2v20"/><path d="M21 15V2a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3zm0 0v7"/>']
    ],
    'fruits-vegetables': [
      ['irrigation', 'Pivot Irrigation', 'Runs and water use', '<path d="M12 2.7l5.7 5.7a8 8 0 1 1-11.4 0z"/>'],
      ['grading', 'Harvest Grading', 'Grades and rejects', '<path d="M12 3l2.9 5.9 6.5.9-4.7 4.6 1.1 6.5L12 17.8 6.2 20.9l1.1-6.5L2.6 9.8l6.5-.9z"/>']
    ]
  };

  // Crops whose Production Crop.desk_launcher is "Crop Production desk" (roses and other
  // flowers) are run from the Crop Production desk pages, not the Production app, so their
  // tiles open those instead. [label, subtitle, href, icon].
  var DESK_VIEWS = [
    ['Crop Cycles', 'Planting to uprooting', '/app/crop-cycle', '<path d="M7 20h10"/><path d="M10 20c5.5-2.5.8-6.4 3-10"/><path d="M9.5 9.4c1.1.8 1.8 2.2 2.3 3.7-2 .4-3.5.4-4.8-.3-1.2-.6-2.3-1.9-3-4.2 2.8-.5 4.4 0 5.5.8z"/><path d="M14.1 6a7 7 0 0 0-1.1 4c1.9-.1 3.3-.6 4.3-1.4 1-1 1.6-2.3 1.7-4.6-2.7.1-4 1-4.9 2z"/>'],
    ['Greenhouses', 'Houses, beds and plantings', '/app/greenhouse', '<path d="M3 21V10l9-7 9 7v11"/><path d="M3 14h18M9 14v7M15 14v7"/>'],
    ['Crop Protocols', 'Variety recipe, density and yield', '/app/crop-protocol', '<path d="M12 2v6l3-2 3 2V2"/><path d="M4 22V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v16"/><path d="M8 12h8M8 16h6"/>'],
    ['Cut Stages', 'Harvest cut definitions', '/app/cut-stage', '<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="M20 4 8.12 15.88M14.47 14.48 20 20M8.12 8.12 12 12"/>'],
    ['Production Plan Form', 'Weekly plan and tasks', '/app/production-plan-form', '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/><path d="m9 16 2 2 4-4"/>'],
    ['Harvesting', 'Stock entries for the cut', '/app/stock-entry?stock_entry_type=Harvesting', '<path d="M21 8 12 3 3 8v8l9 5 9-5z"/><path d="m3 8 9 5 9-5M12 13v8"/>'],
    ['Farm Map', 'What is planted where', '/budget-forecast#map', '<path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="3"/>'],
    ['Agriculture Settings', 'Defaults and rates', '/app/agriculture-settings', '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>']
  ];
  // The field is authoritative; a server that has not reloaded since the field was added does not
  // send it, and then a crop whose units are Greenhouse -> Bed is a flower crop.
  function usesDesk(crop) {
    if (crop.desk_launcher) return crop.desk_launcher === 'Crop Production desk';
    return crop.unit_label === 'Greenhouse';
  }
  var deskKeys = {};

  // Bees and fish run in hives and ponds, not crop cycles. Uses the Production Crop
  // flag from the bootstrap, falling back to the crop key.
  function usesCycles(crop) {
    if (crop.uses_crop_cycles !== undefined && crop.uses_crop_cycles !== null) return !!Number(crop.uses_crop_cycles);
    return ['apiary', 'aquaculture'].indexOf(crop.crop_key) < 0;
  }

  function section(crop) {
    var colour = /^#[0-9a-f]{6}$/i.test(crop.accent_color || '') ? crop.accent_color : '#3f7d3a';
    var cycles = usesCycles(crop);
    var base = VIEWS.filter(function(v) { return cycles || v[0] !== 'cycles'; });
    // The generic Blocks tile uses the crop's own word for its unit (Ponds, Hive Groups).
    base = base.map(function(v) {
      return v[0] === 'blocks' && crop.unit_label ? ['blocks', crop.unit_label + 's', 'Units and areas', v[3]] : v;
    });
    var views = base.slice(0, 1).concat([APPROVALS]).concat(base.slice(1)).concat([MAP]).concat(EXTRA[crop.crop_key] || []);
    // [key, label, subtitle, icon, href]; the desk tiles carry their own href
    views = usesDesk(crop)
      ? DESK_VIEWS.map(function(v) { return [v[0], v[0], v[1], v[3], v[2]]; })
      : views.map(function(v) { return v.concat(['/production_app#/' + encodeURIComponent(crop.crop_key) + '/' + v[0]]); });
    var tiles = views.map(function(v) {
      var href = v[4];
      return '<a class="prn-tile" href="' + esc(href) + '">'
        + '<span class="prn-ic" style="background:' + colour + '1a;color:' + colour + '">'
        + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
        + v[3] + '</svg></span>'
        + '<span class="prn-tx"><span class="prn-lb">' + esc(v[1]) + '</span>'
        + '<span class="prn-sub">' + esc(v[2]) + '</span></span></a>';
    }).join('');
    return '<section class="prn-crop">'
      + '<div class="prn-crophead"><span class="prn-dot" style="background:' + colour + '"></span>'
      + '<span class="prn-cropname">' + esc(crop.name) + '</span></div>'
      + '<div class="prn-grid">' + tiles + '</div>'
      + '</section>';
  }

  function render(crops) {
    if (!crops || !crops.length) {
      if (empty) empty.hidden = false;
      return;
    }
    if (empty) empty.hidden = true;
    crops.forEach(function(c) { if (usesDesk(c)) deskKeys[c.crop_key] = 1; });
    host.innerHTML = crops.map(section).join('');
  }

  // "Awaiting approval" strip: pending submissions per crop, stale ones in red.
  var awaitBox = root_element.querySelector('[data-prn-await]');
  var awaitRow = root_element.querySelector('[data-prn-await-row]');
  function renderAwait(res) {
    if (!awaitBox || !awaitRow || !res || !res.crops || !res.crops.length) return;
    // approvals for desk-launched crops are not reviewed in the Production app
    var rows = res.crops.filter(function(c) { return !deskKeys[c.crop_key]; });
    if (!rows.length) return;
    awaitRow.innerHTML = rows.map(function(c) {
      var href = '/production_app#/' + encodeURIComponent(c.crop_key || '') + '/approvals';
      var protos = Number(c.protocols_pending) || 0;
      return '<a class="prn-chip" href="' + esc(href) + '"><span class="prn-chip-n">' + (c.pending || 0) + '</span>'
        + '<span class="prn-chip-l">' + esc(c.crop) + '</span>'
        + (protos ? '<span class="prn-proto">' + protos + (protos === 1 ? ' protocol' : ' protocols') + '</span>' : '')
        + (c.stale ? '<span class="prn-stale">' + c.stale + ' stale</span>' : '') + '</a>';
    }).join('');
    awaitBox.hidden = false;
  }

  if (window.frappe && frappe.call) {
    frappe.call({
      method: 'upande_production.api.production.get_bootstrap',
      callback: function(r) {
        render(r && r.message && r.message.crops);
        frappe.call({
          method: 'upande_production.api.approvals.approval_counts',
          callback: function(r2) { var m = r2 && r2.message; if (m && !m.error) renderAwait(m); }
        });
      },
      error: function() { if (empty) empty.hidden = false; }
    });
  } else if (empty) {
    empty.hidden = false;
  }
})();

style:
.prn{padding:4px 2px;font-family:'Poppins',var(--font-stack),'Inter',sans-serif;}
.prn-title{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#8a8f98;font-weight:600;margin:0 0 12px 2px;}
.prn-crop{padding:0 0 18px;}
.prn-crop:last-child{padding-bottom:4px;}
.prn-crophead{display:flex;align-items:center;gap:9px;margin:0 0 9px 2px;}
.prn-dot{width:10px;height:10px;border-radius:50%;flex:0 0 auto;}
.prn-cropname{font-size:14px;font-weight:600;letter-spacing:-.01em;}
.prn-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px;}
.prn-tile{display:flex;align-items:center;gap:11px;padding:13px 15px;border:1px solid var(--border-color,#e2e4e9);border-radius:10px;background:var(--card-bg,#fff);text-decoration:none;color:inherit;transition:box-shadow .18s ease,transform .18s ease;}
.prn-tile:hover{box-shadow:0 2px 6px rgba(0,0,0,.06);transform:translateY(-1px);text-decoration:none;}
.prn-ic{width:36px;height:36px;border-radius:9px;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.prn-ic svg{width:18px;height:18px;}
.prn-tx{display:flex;flex-direction:column;min-width:0;}
.prn-lb{font-size:13px;font-weight:600;letter-spacing:-.01em;}
.prn-sub{font-size:11px;color:#8a8f98;margin-top:1px;}
.prn-empty{font-size:12px;color:#8a8f98;padding:8px 2px;}
.prn-await{margin:0 0 20px;}
.prn-await-title{margin-bottom:8px;}
.prn-await-row{display:flex;flex-wrap:wrap;gap:8px;}
.prn-chip{display:inline-flex;align-items:center;gap:8px;padding:7px 13px;border:1px solid var(--border-color,#e2e4e9);border-radius:999px;background:var(--card-bg,#fff);text-decoration:none;color:inherit;font-size:12px;transition:box-shadow .18s ease;}
.prn-chip:hover{box-shadow:0 2px 6px rgba(0,0,0,.06);text-decoration:none;}
.prn-chip-n{font-weight:700;font-size:14px;font-variant-numeric:tabular-nums;}
.prn-chip-l{color:#5b6068;font-weight:500;}
.prn-stale{color:#d6342b;font-weight:600;font-size:11px;background:#d6342b14;border-radius:999px;padding:1px 8px;}
.prn-proto{color:#8a5a00;font-weight:600;font-size:11px;background:#e8a31a1f;border-radius:999px;padding:1px 8px;}

script:
(function() {
  // Poppins - document-level so it reaches this block's shadow root.
  try {
    if (!document.querySelector('link[data-rpn-poppins]')) {
      var pf=document.createElement('link'); pf.rel='stylesheet'; pf.setAttribute('data-rpn-poppins','1');
      pf.href='https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap';
      document.head.appendChild(pf);
    }
  } catch(e){}

  // Role-gate tiles: data-roles="" shows for everyone; otherwise only if the
  // user holds one of the listed roles. System Manager / Administrator see all.
  var roles = (window.frappe && frappe.user_roles) || [];
  var isAdmin = roles.indexOf('System Manager') >= 0
    || roles.indexOf('Administrator') >= 0
    || (window.frappe && frappe.user && frappe.user.name === 'Administrator');
  root_element.querySelectorAll('.rpn-tile').forEach(function(tile) {
    var req = (tile.getAttribute('data-roles') || '')
      .split(',').map(function(s){return s.trim();}).filter(Boolean);
    if (req.length === 0) return;
    var ok = isAdmin || req.some(function(r){ return roles.indexOf(r) >= 0; });
    if (!ok) tile.classList.add('rpn-hide');
  });

  // One tile per Farm, so a grower lands on their own greenhouses.
  var farmGrid  = root_element.querySelector('[data-rpn-farms]');
  var farmTitle = root_element.querySelector('[data-rpn-farms-title]');
  function hideFarms() {
    if (farmTitle) farmTitle.classList.add('rpn-hide');
    if (farmGrid) farmGrid.classList.add('rpn-hide');
  }
  if (farmGrid && window.frappe && frappe.call) {
    frappe.call({
      method: 'frappe.client.get_list',
      args: { doctype: 'Farm', fields: ['name'], limit_page_length: 0, order_by: 'name asc' },
      callback: function(r) {
        var farms = (r && r.message) || [];
        if (!farms.length) { hideFarms(); return; }
        var ic = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
               + ' stroke-linecap="round" stroke-linejoin="round">'
               + '<path d="M3 21V10l9-7 9 7v11"/><line x1="3" y1="14" x2="21" y2="14"/>'
               + '<line x1="9" y1="14" x2="9" y2="21"/><line x1="15" y1="14" x2="15" y2="21"/></svg>';
        farms.forEach(function(f) {
          var a = document.createElement('a');
          a.className = 'rpn-tile';
          a.setAttribute('data-roles', '');
          a.href = '/app/greenhouse?farm=' + encodeURIComponent(f.name);
          a.innerHTML =
            '<span class="rpn-ic" style="background:rgba(22,163,74,.13);color:#16a34a">' + ic + '</span>'
            + '<span class="rpn-tx"><span class="rpn-lb"></span>'
            + '<span class="rpn-sub">Greenhouses on this farm</span></span>';
          a.querySelector('.rpn-lb').textContent = f.name;
          farmGrid.appendChild(a);
        });
      },
      error: hideFarms
    });
  } else { hideFarms(); }

  // Hide a section label if every tile under it is hidden.
  root_element.querySelectorAll('.rpn-sec').forEach(function(t){
    if (t.hasAttribute('data-rpn-farms-title')) return;
    var grid = t.nextElementSibling;
    if (!grid || !grid.classList.contains('rpn-grid')) return;
    var vis = grid.querySelectorAll('.rpn-tile:not(.rpn-hide)').length;
    if (!vis) { t.classList.add('rpn-hide'); grid.classList.add('rpn-hide'); }
  });
})();

(function () {
  var $ = function (s) { return root_element.querySelector(s); };
  var tip = $('[data-ccd-tip]');

  function fmt(n) {
    n = Number(n || 0);
    if (n >= 1e6) return (n / 1e6).toFixed(n >= 1e7 ? 0 : 1).replace(/\.0$/, '') + 'M';
    if (n >= 1e4) return Math.round(n / 1e3) + 'K';
    return n.toLocaleString();
  }
  function esc(s) { var d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }
  function showTip(e, html) {
    tip.innerHTML = html; tip.classList.add('on');
    var r = tip.getBoundingClientRect();
    var x = Math.min(e.clientX + 12, window.innerWidth - r.width - 8);
    var y = Math.max(e.clientY - r.height - 10, 8);
    tip.style.left = x + 'px'; tip.style.top = y + 'px';
  }
  function hideTip() { tip.classList.remove('on'); }

  // one measure across categories -> one hue, bars sorted by magnitude
  function bars(host, rows, unitLabel) {
    host.innerHTML = '';
    if (!rows.length) { host.innerHTML = '<div class="ccd-empty">No data yet.</div>'; return; }
    var max = Math.max.apply(null, rows.map(function (r) { return r.value; })) || 1;
    rows.forEach(function (r) {
      var row = document.createElement('div'); row.className = 'ccd-bar-row';
      row.innerHTML = '<div class="ccd-bar-lb" title="' + esc(r.label) + '">' + esc(r.label) + '</div>'
        + '<div class="ccd-track"><div class="ccd-fill" style="width:' + (r.value / max * 100).toFixed(1) + '%"></div></div>'
        + '<div class="ccd-bar-vl">' + fmt(r.value) + '</div>';
      var fill = row.querySelector('.ccd-fill');
      fill.addEventListener('mousemove', function (e) {
        showTip(e, '<b>' + esc(r.label) + '</b><br>' + Number(r.value).toLocaleString() + ' ' + unitLabel
          + (r.note ? '<br>' + esc(r.note) : ''));
      });
      fill.addEventListener('mouseleave', hideTip);
      host.appendChild(row);
    });
  }

  function getList(doctype, fields, extra) {
    var args = { doctype: doctype, fields: fields, limit_page_length: 0 };
    if (extra) Object.keys(extra).forEach(function (k) { args[k] = extra[k]; });
    return new Promise(function (res, rej) {
      frappe.call({ method: 'frappe.client.get_list', args: args,
        callback: function (r) { res((r && r.message) || []); }, error: rej });
    });
  }

  function load() {
    $('[data-ccd-sub]').textContent = 'Loading…';
    Promise.all([
      getList('Greenhouse', ['name', 'farm', 'number_of_beds', 'number_of_plants',
                             'area_planted', 'gross_area', 'varieties']),
      getList('Crop Cycle', ['name', 'greenhouse', 'farm', 'variety', 'status',
                             'qty_planted', 'plants_standing', 'planted_area'])
    ]).then(function (out) {
      var ghs = out[0], ccs = out[1];

      // ---- KPIs ----
      var beds = 0, plants = 0, planted = 0, gross = 0;
      ghs.forEach(function (g) {
        beds += g.number_of_beds || 0; plants += g.number_of_plants || 0;
        planted += g.area_planted || 0; gross += g.gross_area || 0;
      });
      var varieties = {};
      var active = 0;
      ccs.forEach(function (c) { if (c.variety) varieties[c.variety] = 1; if (c.status === 'Active') active++; });
      var util = gross ? (planted / gross * 100) : 0;

      var kpis = [
        { l: 'Plants standing', v: fmt(plants), n: plants.toLocaleString() + ' across all beds', hero: 1 },
        { l: 'Greenhouses', v: ghs.length, n: fmt(beds) + ' beds' },
        { l: 'Planted area', v: fmt(Math.round(planted)) + ' m²', n: util.toFixed(0) + '% of ' + fmt(Math.round(gross)) + ' m² gross' },
        { l: 'Crop cycles', v: ccs.length, n: active + ' active' },
        { l: 'Varieties in ground', v: Object.keys(varieties).length, n: 'distinct, from crop cycles' }
      ];
      $('[data-ccd-kpis]').innerHTML = kpis.map(function (k) {
        return '<div class="ccd-kpi' + (k.hero ? ' ccd-kpi-hero' : '') + '">'
          + '<div class="ccd-kpi-l">' + esc(k.l) + '</div>'
          + '<div class="ccd-kpi-v">' + esc(String(k.v)) + '</div>'
          + '<div class="ccd-kpi-n">' + esc(k.n) + '</div></div>';
      }).join('');

      // ---- plants by farm (from the beds) ----
      var byFarm = {};
      ghs.forEach(function (g) {
        var f = g.farm || '(no farm)';
        byFarm[f] = byFarm[f] || { value: 0, ghs: 0, beds: 0 };
        byFarm[f].value += g.number_of_plants || 0;
        byFarm[f].ghs += 1; byFarm[f].beds += g.number_of_beds || 0;
      });
      bars($('[data-ccd-farms]'), Object.keys(byFarm).map(function (f) {
        return { label: f, value: byFarm[f].value,
                 note: byFarm[f].ghs + ' greenhouses · ' + byFarm[f].beds.toLocaleString() + ' beds' };
      }).sort(function (a, b) { return b.value - a.value; }), 'plants');

      // ---- top varieties, by plants from the cycles ----
      var byVar = {};
      ccs.forEach(function (c) {
        if (!c.variety) return;
        byVar[c.variety] = byVar[c.variety] || { value: 0, n: 0 };
        byVar[c.variety].value += c.plants_standing || c.qty_planted || 0;
        byVar[c.variety].n += 1;
      });
      var vrows = Object.keys(byVar).map(function (v) {
        return { label: v, value: byVar[v].value, note: byVar[v].n + ' crop cycle(s)' };
      }).sort(function (a, b) { return b.value - a.value; });
      bars($('[data-ccd-varieties]'), vrows.slice(0, 10), 'plants');

      // ---- status chips (icon/label always, never colour alone) ----
      var st = {}; ccs.forEach(function (c) { st[c.status || 'Not set'] = (st[c.status || 'Not set'] || 0) + 1; });
      var COLOUR = { Active: 'var(--ccd-good)', Ended: 'var(--ccd-critical)', Planned: 'var(--ccd-warning)' };
      $('[data-ccd-status]').innerHTML = Object.keys(st).sort().map(function (k) {
        return '<span class="ccd-chip"><span class="ccd-dot" style="background:'
          + (COLOUR[k] || 'var(--text-muted)') + '"></span>' + esc(k) + ' <b>' + st[k] + '</b></span>';
      }).join('') || '<div class="ccd-empty">No crop cycles yet.</div>';

      // ---- table ----
      var ccByGh = {};
      ccs.forEach(function (c) { ccByGh[c.greenhouse] = (ccByGh[c.greenhouse] || 0) + 1; });
      var rows = ghs.slice().sort(function (a, b) { return (b.number_of_plants || 0) - (a.number_of_plants || 0); });
      $('[data-ccd-tbody]').innerHTML = rows.map(function (g) {
        var noCycle = !ccByGh[g.name];
        return '<tr' + (noCycle ? ' class="ccd-warn"' : '') + '>'
          + '<td><a href="/app/greenhouse/' + encodeURIComponent(g.name) + '">' + esc(g.name) + '</a></td>'
          + '<td>' + esc(g.farm || '—') + '</td>'
          + '<td class="num">' + (g.number_of_beds || 0).toLocaleString() + '</td>'
          + '<td class="num">' + (g.number_of_plants || 0).toLocaleString() + '</td>'
          + '<td class="num">' + Math.round(g.area_planted || 0).toLocaleString() + '</td>'
          + '<td class="num">' + Math.round(g.gross_area || 0).toLocaleString() + '</td>'
          + '<td class="num">' + (g.varieties || 0) + '</td>'
          + '<td class="num">' + (ccByGh[g.name] || 0) + '</td></tr>';
      }).join('');
      var missing = rows.filter(function (g) { return !ccByGh[g.name]; }).length;
      $('[data-ccd-tbl-sub]').textContent = rows.length + ' greenhouses'
        + (missing ? ' · ' + missing + ' shaded rows have beds but no crop cycle' : '');
      $('[data-ccd-sub]').textContent = ghs.length + ' greenhouses · ' + fmt(beds)
        + ' beds · ' + ccs.length + ' crop cycles';
    }).catch(function (e) {
      $('[data-ccd-sub]').textContent = 'Could not load: ' + (e && e.message ? e.message : 'request failed');
    });
  }

  var btn = $('[data-ccd-refresh]');
  if (btn) btn.addEventListener('click', load);
  load();
})();

style:
.ccd { font-family: var(--font-stack), system-ui, sans-serif; padding: 2px; }
.ccd-hd { display:flex; align-items:flex-end; justify-content:space-between; gap:12px; margin:0 0 14px 2px; flex-wrap:wrap; }
.ccd-tt { font-size:18px; font-weight:700; color:var(--heading-color,#0b0b0b); line-height:1.1; }
.ccd-sub { font-size:12px; color:var(--text-muted,#898781); margin-top:3px; }
.ccd-btn { border:1px solid var(--border-color,#e1e0d9); background:var(--card-bg,#fff); color:var(--text-muted,#52514e);
  border-radius:7px; padding:6px 12px; font-size:12px; font-weight:600; cursor:pointer; }
.ccd-btn:hover { color:var(--text-color,#0b0b0b); }

/* ---- stat tiles ---- */
.ccd-kpis { display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:10px; margin-bottom:14px; }
.ccd-kpi { border:1px solid var(--border-color,#e1e0d9); border-radius:10px; background:var(--card-bg,#fff); padding:12px 14px; }
.ccd-kpi-l { font-size:11px; color:var(--text-muted,#898781); font-weight:600; letter-spacing:.02em; }
.ccd-kpi-v { font-size:24px; font-weight:650; color:var(--text-color,#0b0b0b); line-height:1.15; margin-top:5px; }
.ccd-kpi-hero .ccd-kpi-v { font-size:40px; }
.ccd-kpi-n { font-size:11px; color:var(--text-muted,#898781); margin-top:3px; }

/* ---- panels ---- */
.ccd-row { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:14px; }
.ccd-card { border:1px solid var(--border-color,#e1e0d9); border-radius:10px; background:var(--card-bg,#fff); padding:14px 16px 16px; min-width:0; }
.ccd-card-t { font-size:13px; font-weight:650; color:var(--text-color,#0b0b0b); }
.ccd-card-s { font-size:11px; color:var(--text-muted,#898781); margin-top:2px; margin-bottom:12px; }

/* ---- horizontal bars: one measure, one hue ---- */
.ccd-bars { display:flex; flex-direction:column; gap:9px; }
.ccd-bar-row { display:grid; grid-template-columns:96px 1fr auto; align-items:center; gap:10px; }
.ccd-bar-lb { font-size:12px; color:var(--text-color,#0b0b0b); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.ccd-track { height:16px; background:var(--control-bg,#f4f4f2); border-radius:3px; position:relative; overflow:hidden; }
.ccd-fill { height:100%; background:var(--ccd-series); border-radius:0 4px 4px 0; min-width:2px;
  transition:width .35s ease; cursor:pointer; }
.ccd-bar-vl { font-size:12px; color:var(--text-muted,#52514e); font-variant-numeric:tabular-nums; white-space:nowrap; }

/* ---- status chips: colour never alone ---- */
.ccd-chips { display:flex; gap:8px; flex-wrap:wrap; margin-top:2px; }
.ccd-chip { display:inline-flex; align-items:center; gap:6px; border:1px solid var(--border-color,#e1e0d9);
  border-radius:999px; padding:5px 11px; font-size:12px; color:var(--text-color,#0b0b0b); background:var(--card-bg,#fff); }
.ccd-dot { width:9px; height:9px; border-radius:50%; flex:0 0 auto; }
.ccd-chip b { font-variant-numeric:tabular-nums; }

/* ---- table ---- */
.ccd-scroll { overflow-x:auto; }
.ccd-tb { width:100%; border-collapse:collapse; font-size:12px; }
.ccd-tb th { text-align:left; font-weight:600; color:var(--text-muted,#898781); font-size:11px;
  padding:7px 10px; border-bottom:1px solid var(--border-color,#e1e0d9); white-space:nowrap; }
.ccd-tb td { padding:7px 10px; border-bottom:1px solid var(--border-color,#e1e0d9); color:var(--text-color,#0b0b0b); white-space:nowrap; }
.ccd-tb tr:last-child td { border-bottom:0; }
.ccd-tb .num { text-align:right; font-variant-numeric:tabular-nums; }
.ccd-tb a { color:var(--ccd-series); text-decoration:none; }
.ccd-tb a:hover { text-decoration:underline; }
.ccd-warn td { background:rgba(250,178,25,.08); }

/* ---- tooltip ---- */
.ccd-tip { position:fixed; z-index:9999; pointer-events:none; opacity:0; transition:opacity .12s;
  background:var(--text-color,#0b0b0b); color:var(--card-bg,#fff); font-size:11.5px; line-height:1.45;
  padding:6px 9px; border-radius:6px; max-width:240px; }
.ccd-tip.on { opacity:1; }
.ccd-empty { font-size:12px; color:var(--text-muted,#898781); padding:10px 2px; }

/* ---- colour tokens: light is the base, dark redefined under both scopes ---- */
.ccd { --ccd-series:#2a78d6; --ccd-good:#0ca30c; --ccd-warning:#fab219; --ccd-critical:#d03b3b; }
@media (prefers-color-scheme: dark) {
  :root:where(:not([data-theme="light"])) .ccd { --ccd-series:#3987e5; }
}
:root[data-theme="dark"] .ccd { --ccd-series:#3987e5; }
[data-theme="dark"] .ccd-track { background:rgba(255,255,255,.07); }

@media (max-width: 900px) { .ccd-row { grid-template-columns:1fr; } }
